const $=id=>document.getElementById(id), C=MedicineCore, labels={eye:'안약',ointment:'연고',syrup:'시럽'};
let medicines=[], family='', editing=null, recognition=null, noticeTimer;
try {const data=JSON.parse(localStorage.getItem('medicine-note-v1')||'{}');medicines=Array.isArray(data.medicines)?data.medicines.filter(m=>m && typeof m.id==='string' && labels[m.kind] && typeof m.name==='string' && /^\d{4}-\d{2}-\d{2}$/.test(m.opened) && Number.isInteger(m.days) && m.days>0 && m.days<=3650 && (!m.printed || /^\d{4}-\d{2}-\d{2}$/.test(m.printed))):[];family=typeof data.family==='string'?data.family:'';}catch {showNotice('저장된 기록을 읽지 못했어요. 브라우저 저장 설정을 확인해 주세요.');}
function showNotice(text){$('notice').textContent=text;$('notice').hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').hidden=true,10000);}
function persist(){try{localStorage.setItem('medicine-note-v1',JSON.stringify({medicines,family}));return true;}catch{showNotice('저장 공간을 사용할 수 없어요. 기록이 저장되지 않았습니다.');return false;}}
function speak(text){if('speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=.9;speechSynthesis.speak(u);}}
function dateLabel(s){return s.replaceAll('-','. ');}
function render(){
 $('count').textContent=medicines.length;const root=$('medicines');root.replaceChildren();
 if(!medicines.length){const empty=document.createElement('div');empty.className='empty';empty.textContent='아직 등록한 약이 없어요. 위에서 오늘 연 약을 기록해 보세요.';root.append(empty);}
 [...medicines].sort((a,b)=>C.deadline(a).localeCompare(C.deadline(b))).forEach(m=>{
  const left=C.remaining(m), card=document.createElement('article');card.className='card '+(left<=0?'expired':left<=7?'soon':'');
  const top=document.createElement('div');top.className='card-top';const title=document.createElement('h3');title.textContent=m.name;const badge=document.createElement('span');badge.className='tag';badge.textContent=left<0?`${-left}일 지났어요`:left===0?'오늘이 기한이에요':`${left}일 남았어요`;top.append(title,badge);
  const dates=document.createElement('p');dates.className='dates';dates.textContent=`${labels[m.kind]} · 개봉 ${dateLabel(m.opened)}`;const due=document.createElement('p');due.textContent=`사용기한 ${dateLabel(C.deadline(m))}`;
  const actions=document.createElement('div');actions.className='row';const edit=document.createElement('button');edit.textContent='수정';edit.onclick=()=>openRecord(m.kind,m);const remove=document.createElement('button');remove.textContent='삭제';remove.onclick=()=>{if(confirm(`${m.name} 기록을 삭제할까요?`)){const previous=medicines;medicines=medicines.filter(x=>x.id!==m.id);if(!persist())medicines=previous;render();}};actions.append(edit,remove);
  if(left<=7){const sms=document.createElement('a');sms.className='sms';sms.textContent='가족에게 문자';if(family){const body=`[약 챙김] ${m.name}의 사용기한은 ${C.deadline(m)}입니다. ${left<=0?'사용기한이 되었어요.':'기한이 얼마 남지 않았어요.'} 함께 확인해 주세요.`;sms.href=`sms:${family}?body=${encodeURIComponent(body)}`;}else{sms.href='#phone';sms.onclick=()=>{$('phone').closest('details').open=true;$('phone').focus();showNotice('가족 번호를 먼저 저장해 주세요.');};}actions.append(sms);}
  card.append(top,dates,due,actions);root.append(card);
 });
}
function applyPreset(){const kind=$('kind').value;$('days').value=C.presetDays(kind,$('opened').value||C.today());$('periodHint').textContent=kind==='syrup'?'제품에 안내된 개봉 후 사용일수를 직접 입력해 주세요.':`기획서 시연값: ${kind==='eye'?'1개월':'6개월'}. 제품 설명에 맞게 일수를 수정하세요.`;}
function openRecord(kind,existing=null,name=''){editing=existing?.id||null;$('recordForm').reset();$('formError').textContent='';$('kind').value=kind;$('name').value=existing?.name||name||labels[kind];$('opened').value=existing?.opened||C.today();$('opened').max=C.today();applyPreset();if(existing){$('days').value=existing.days;$('printed').value=existing.printed||'';}$('recordDialog').showModal();speak(`${$('name').value} 맞나요? 제품에 적힌 사용기한도 확인해 주세요.`);}
document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>openRecord(b.dataset.kind));$('kind').onchange=applyPreset;$('opened').onchange=applyPreset;$('cancel').onclick=()=>$('recordDialog').close();
$('recordForm').onsubmit=e=>{e.preventDefault();const name=$('name').value.trim(), opened=$('opened').value, days=Number($('days').value),printed=$('printed').value;if(!name||opened>C.today()||!Number.isInteger(days)||days<1||days>3650){$('formError').textContent='약 이름, 개봉일, 사용일수를 확인해 주세요.';return;}if(printed&&printed<opened){$('formError').textContent='포장 유효기간이 개봉일보다 빠릅니다. 날짜를 확인해 주세요.';return;}const m={id:editing||crypto.randomUUID(),name,kind:$('kind').value,opened,days,printed};const previous=medicines;medicines=editing?medicines.map(x=>x.id===editing?m:x):[...medicines,m];if(!persist()){medicines=previous;return;}$('recordDialog').close();render();showNotice(`${name}, 개봉일을 저장했어요.`);speak(`${name}, 저장했어요.`);checkDue(false);};
const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;
$('mic').onclick=()=>{
 if(!Speech){$('voiceStatus').textContent='이 브라우저는 음성 인식을 지원하지 않아요. 아래 종류 버튼으로 기록해 주세요.';return;}
 if(recognition){recognition.stop();return;}
 const r=new Speech();recognition=r;r.lang='ko-KR';r.interimResults=false;r.maxAlternatives=1;
 r.onstart=()=>{$('mic').classList.add('listening');$('mic').querySelector('span').textContent='듣고 있어요';$('voiceStatus').textContent='약 이름을 말씀하세요. 다시 누르면 멈춰요.';};
 r.onresult=e=>{const result=e.results[0][0], text=result.transcript.trim(),name=text.replace(/\s*(열었어요|열었어|개봉했어요|개봉했어|개봉|열었다)[.!?]?\s*$/,'').trim();const kind=/안약|인공\s*눈물|점안/.test(text)?'eye':/연고|크림/.test(text)?'ointment':/시럽|물약/.test(text)?'syrup':null;$('voiceStatus').textContent=`“${text}”라고 들었어요.`;if(kind&&name&&(result.confidence===0||result.confidence>=.55)){openRecord(kind,null,name.slice(0,60));}else{$('voiceStatus').textContent='정확히 알아듣지 못했어요. 안약, 연고, 시럽 중 골라 주세요.';speak('약 종류를 아래에서 골라 주세요.');}};
 r.onerror=e=>{$('voiceStatus').textContent=e.error==='not-allowed'?'마이크 사용이 허용되지 않았어요. 아래 종류 버튼으로 기록해 주세요.':'말씀을 듣지 못했어요. 다시 누르거나 아래 종류를 골라 주세요.';};r.onend=()=>{recognition=null;$('mic').classList.remove('listening');$('mic').querySelector('span').textContent='눌러서 말하기';};try{r.start();}catch{recognition=null;$('voiceStatus').textContent='음성 인식을 시작하지 못했어요. 아래 종류 버튼을 이용해 주세요.';}
};
$('phone').value=family;$('familyForm').onsubmit=e=>{e.preventDefault();const value=$('phone').value.replace(/[\s()-]/g,'');if(value&&!/^\+?\d{9,15}$/.test(value)){showNotice('전화번호를 확인해 주세요.');return;}const previous=family;family=value;if(persist()){render();showNotice(value?'가족 번호를 저장했어요. 문자 전송은 직접 확인해 주세요.':'가족 번호를 지웠어요.');}else family=previous;};
function notificationState(){$('notificationState').textContent=!('Notification'in window)?'이 브라우저에서는 시스템 알림을 지원하지 않아요.':Notification.permission==='granted'?'브라우저 알림이 켜져 있어요.':Notification.permission==='denied'?'브라우저 설정에서 알림 권한을 허용해 주세요.':'알림 권한을 허용하면 기한을 알려드려요.';}
$('enableNotify').onclick=async()=>{if(!('Notification'in window)){notificationState();return;}try{await Notification.requestPermission();notificationState();checkDue(true);}catch{showNotice('알림을 켜지 못했어요. 화면에서 기한을 확인해 주세요.');}};
const alerted=new Set();
function checkDue(manual=false){render();const due=medicines.filter(m=>C.remaining(m)<=7);if(manual)showNotice(due.length?`${due.length}개의 약이 기한 확인이 필요해요. 약 카드를 확인하세요.`:'사용기한이 임박한 약이 없어요.');due.forEach(m=>{const key=m.id+C.deadline(m)+C.today();if(alerted.has(key))return;alerted.add(key);const text=`${m.name}, ${C.remaining(m)<=0?'사용기한이 되었어요.':'사용기한이 얼마 남지 않았어요.'} 제품을 확인해 주세요.`;if('Notification'in window&&Notification.permission==='granted'){try{new Notification('약 챙김 — 기한 알림',{body:text,tag:m.id});}catch{showNotice(text);}}else showNotice(text);if(manual)speak(text);});}
$('check').onclick=()=>checkDue(true);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkDue(false);});notificationState();checkDue(false);setInterval(()=>checkDue(false),60000);
